ALTER TABLE "tunnel_attachments" ADD CONSTRAINT "tunnel_attachments_local_endpoint_check" CHECK (("tunnel_attachments"."kind" = 'desktop-loopback' AND "tunnel_attachments"."client_id" IS NOT NULL AND (("tunnel_attachments"."local_host" IS NULL AND "tunnel_attachments"."local_port" IS NULL) OR ("tunnel_attachments"."local_host" IN ('127.0.0.1', 'localhost', '::1') AND "tunnel_attachments"."local_port" BETWEEN 1 AND 65535))) OR ("tunnel_attachments"."kind" = 'server-relay' AND "tunnel_attachments"."client_id" IS NULL AND "tunnel_attachments"."local_host" IS NULL AND "tunnel_attachments"."local_port" IS NULL));